present = []

while True:
    parts = input().split()
    cmd = parts[0]
    if cmd == "end":
        break
    elif cmd == "in":
        if parts[1] in present:
            print("이미 출석")
        else:
            present.append(parts[1])
    elif cmd == "out":
        if parts[1] in present:
            present.remove(parts[1])
        else:
            print("출석하지 않음")
    elif cmd == "list":
        if present:
            print(*sorted(present))
        else:
            print("아무도 없음")
